function normalizeLanguageCode(lang){const l=String(lang||'').trim().toLowerCase();return l==='en-us'||l==='en_us'?'en':l;}
function trText(text,lang){if(!text)return '';const key=String(text);const l=String(lang||'').toLowerCase();if(l==='ms')return key;const normalized=normalizeLanguageCode(lang);return state.translations[normalized+'|'+key]||key;}
function trName(text,lang){const key=String(text||'');const l=String(lang||'').toLowerCase();if(l==='ms'||l==='en')return key;const normalized=normalizeLanguageCode(lang);return state.translations[normalized+'|'+key]||key;}
async function translateForLanguage(lang){state.translations={};if(lang==='ms')return;const need=[];for(const x of state.menu){if(lang!=='en')need.push(String(x.name_en||''));need.push(String(x.item_description||''));if(lang!=='en')need.push(String(x.category||''));}const uniq=[...new Set(need.filter(Boolean))];const cached={};try{for(const k of Object.keys(localStorage)){if(k.startsWith('hameeds_tr_'+lang+'|'))cached[k.slice(('hameeds_tr_'+lang+'|').length)]=localStorage.getItem(k)||'';}}catch{}const missing=uniq.filter(x=>!cached[x]);if(missing.length){try{const r=await api('/translate',{method:'POST',body:JSON.stringify({target:lang,texts:missing})});for(const row of (r.data||[])){cached[row.source]=row.text;try{localStorage.setItem('hameeds_tr_'+lang+'|'+row.source,row.text)}catch{}}}catch(e){console.warn('[Hameeds Customer] Translation failed:',e.message)}}for(const x of uniq)if(cached[x])state.translations[lang+'|'+x]=cached[x];}
function T(k){return (ui[state.lang]||ui.en)[k]||ui.en[k]||k}
function CT(k){const d={modify:'Modify',addNote:'Add Note',save:'Save',cancel:'Cancel',customNote:'Custom Note',selectModifiers:'Select modifiers',noModifiers:'No modifiers available',notePlaceholder:'Write a note for this item…',selected:'Selected'};const m={ms:{modify:'Ubah',addNote:'Tambah Nota',save:'Simpan',cancel:'Batal',customNote:'Nota Khas',selectModifiers:'Pilih pengubah',noModifiers:'Tiada pengubah',notePlaceholder:'Tulis nota untuk item ini…',selected:'Dipilih'},hi:{modify:'संशोधित करें',addNote:'नोट जोड़ें',save:'सहेजें',cancel:'रद्द करें',customNote:'कस्टम नोट',selectModifiers:'मॉडिफायर चुनें',noModifiers:'कोई मॉडिफायर नहीं',notePlaceholder:'इस आइटम के लिए नोट लिखें…',selected:'चयनित'},ar:{modify:'تعديل',addNote:'إضافة ملاحظة',save:'حفظ',cancel:'إلغاء',customNote:'ملاحظة مخصصة',selectModifiers:'اختر الإضافات',noModifiers:'لا توجد إضافات',notePlaceholder:'اكتب ملاحظة لهذا العنصر…',selected:'محدد'},bn:{modify:'মডিফাই',addNote:'নোট যোগ করুন',save:'সেভ',cancel:'বাতিল',customNote:'কাস্টম নোট',selectModifiers:'মডিফায়ার বেছে নিন',noModifiers:'কোনো মডিফায়ার নেই',notePlaceholder:'এই আইটেমের জন্য নোট লিখুন…',selected:'নির্বাচিত'},ta:{modify:'மாற்று',addNote:'குறிப்பு சேர்',save:'சேமி',cancel:'ரத்து',customNote:'தனிப்பயன் குறிப்பு',selectModifiers:'மாற்றிகளை தேர்வு',noModifiers:'மாற்றிகள் இல்லை',notePlaceholder:'இந்த பொருளுக்கான குறிப்பை எழுதவும்…',selected:'தேர்ந்தெடுக்கப்பட்டது'}};return (m[state.lang]||d)[k]||d[k];}
function refreshChrome(){const r=$('#refreshBtn');if(r)r.textContent='↻ '+T('refresh');const c=$('#cartBtn');if(c)c.innerHTML='🛒 <span id="cartTop">'+(state.cart.reduce((a,x)=>a+Number(x.qty||0),0))+'</span>';const l=$('#langBtn');if(l)l.textContent='🌐 '+(state.lang==='ms'?'Bahasa':(langs.find(x=>x[0]===state.lang)?.[2]||'Language'));}
function init(){const q=new URLSearchParams(location.search),hasQr=q.has('qr_table')||q.has('qr_key');state.api=(q.get('api')||localStorage.getItem('hameeds_api')||deployApi||'').replace(/\/$/,'');if(hasQr){state.table=(q.get('qr_table')||'').toUpperCase();state.qrKey=q.get('qr_key')||'';state.manualToken='';if(state.table)localStorage.setItem('hameeds_table',state.table);if(state.qrKey)localStorage.setItem('hameeds_qr_key',state.qrKey);localStorage.removeItem('hameeds_manual_table_token');}else{state.table=(localStorage.getItem('hameeds_table')||'').toUpperCase();state.qrKey='';localStorage.removeItem('hameeds_qr_key');}if(state.api)localStorage.setItem('hameeds_api',state.api);if(state.manualToken)localStorage.setItem('hameeds_manual_table_token',state.manualToken);$('#year').textContent=new Date().getFullYear();renderHome();loadData();}
async function api(path,opt={}){if(!state.api)throw new Error('Customer API URL is not configured.');const r=await fetch(state.api+path,{headers:{'Content-Type':'application/json',...(state.customer?.token?{Authorization:'Bearer '+state.customer.token}:{}),...(opt.headers||{})},...opt});const j=await r.json().catch(()=>({}));if(!r.ok||j.ok===false)throw new Error(j.error||('HTTP '+r.status));return j;}
async function loadData(){state.loading=true;const keepCat=state.cat;setLoading();try{const [m,mods]=await Promise.all([api('/menu'),api('/modifiers')]);state.menu=Array.isArray(m.data)?m.data.filter(x=>Number(x.is_available??1)!==0):[];state.mods=Array.isArray(mods.data)?mods.data:[];state.cats=[...new Set(state.menu.map(x=>String(x.category||'Uncategorized')).filter(Boolean))];state.cat=state.cats.includes(keepCat)?keepCat:'ALL';if(state.lang!=='ms')await translateForLanguage(state.lang);renderCurrent();clearDataError();}catch(e){console.error('[Hameeds Customer] Menu load failed:',e);renderError(e.message);}finally{state.loading=false;}}
function setLoading(){if(state.mode==='home')return;$('#appMain').innerHTML='<div class="home-panel"><div style="display:flex;gap:10px;align-items:center"><span class="spinner"></span><b>'+esc(T('loading'))+'</b></div></div>';}
function renderError(message){clearDataError();const box=document.createElement('div');box.id='customerDataError';box.style.cssText='position:fixed;left:12px;right:12px;bottom:12px;z-index:99999;background:#fff3cd;border:1px solid #e0b100;border-radius:12px;padding:12px 14px;box-shadow:0 8px 24px rgba(0,0,0,.12);font:600 14px/1.4 system-ui,sans-serif;color:#5f4b00;';box.innerHTML='<b>Menu data refresh failed.</b><br>'+esc(String(message||'Unknown error'));document.body.appendChild(box);if(!state.menu.length&&state.mode!=='home')$('#appMain').innerHTML='<section class="home-panel"><div class="notice">'+esc(String(message||'Unable to load menu data.'))+'</div></section>';}
function clearDataError(){const box=document.getElementById('customerDataError');if(box)box.remove();}
function renderHome(){stopSlide();state.mode='home';refreshChrome();$('#appMain').innerHTML=`<section class="home-panel"><div class="home-buttons"><button class="mainbtn" data-mode="dining">🍽️ ${esc(T('dining'))}</button><button class="mainbtn" data-mode="take">🥡 ${esc(T('take'))}</button><button class="mainbtn" data-action="waiter">🔔 ${esc(T('waiter'))}</button><button class="mainbtn" data-mode="history">🧾 ${esc(T('history'))}</button></div><div id="slider" class="slider"><div style="padding:40px;text-align:center;color:#667085">${esc(T('loading'))}</div></div></section>`;document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;renderCurrent();});$('[data-action="waiter"]').onclick=showWaiter;renderSlider();}
function renderCurrent(){stopSlide();if(state.mode==='home'){renderHome();return}if(state.mode==='history'){renderHistory();return}renderMenu();}
function renderMenu(){refreshChrome();const isTake=state.mode==='take';const title=isTake?T('take'):T('dining');const cats=state.cats;$('#appMain').innerHTML=`<section class="home-panel menu-panel"><div class="toolbar menu-controls"><button class="iconbtn" id="backHome">← Home</button><strong style="color:var(--blue)">${esc(title)}</strong><span style="margin-left:auto">${state.table?esc(T('table')+': '+state.table):''}</span><div class="menu-search-row"><select id="catSelect" class="select"><option value="ALL">${esc(T('categories'))}</option>${cats.map(c=>`<option value="${esc(c)}">${esc(displayCategory(c))}</option>`).join('')}</select><div class="search-wrap"><input id="search" class="search" placeholder="${esc(T('search'))}" value="${esc(state.search)}" autocomplete="off"><div id="searchDropdown" class="menu-search-dropdown hidden"></div></div></div><div class="categorybar">${['ALL',...cats].map(c=>`<button class="cat ${state.cat===c?'active':''}" data-cat="${esc(c)}">${esc(c==='ALL'?T('categories'):displayCategory(c))}</button>`).join('')}</div></div><div class="content"><div><div id="menuGrid" class="grid"></div></div></div></section>`;$('#backHome').onclick=()=>{state.search='';renderHome()};$('#catSelect').value=state.cat;$('#catSelect').onchange=e=>{state.cat=e.target.value;state.search='';renderMenu();};const searchEl=$('#search');const dropdown=$('#searchDropdown');searchEl.oninput=e=>{state.search=e.target.value;drawItems(isTake);renderSearchSuggestions(e.target.value);};searchEl.onfocus=()=>renderSearchSuggestions(searchEl.value);document.addEventListener('click',closeSearchDropdown,{once:true});searchEl.addEventListener('click',e=>e.stopPropagation());dropdown.addEventListener('click',e=>e.stopPropagation());document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{state.cat=b.dataset.cat;state.search='';renderMenu();});drawItems(isTake);setupScrollChrome();} 
function closeSearchDropdown(){const d=$('#searchDropdown');if(d)d.classList.add('hidden');}
function renderSearchSuggestions(raw){const d=$('#searchDropdown');if(!d)return;const q=String(raw||'').trim().toLowerCase();if(q.length<2){d.innerHTML='';d.classList.add('hidden');return;}const items=Array.isArray(state.menu)?state.menu:[];const cats=Array.isArray(state.cats)?state.cats:[];const seen=new Set(),suggestions=[];const add=(type,key,label,original,category)=>{const id=type+'|'+String(key);if(seen.has(id))return;seen.add(id);suggestions.push({type,key,label,original,category});};cats.filter(c=>String(c).toLowerCase().includes(q)).slice(0,5).forEach(c=>add('category',c,getCategoryDisplayName(c),c,c));items.filter(x=>{const n=String(x.name_en||'');const c=String(x.category||'Uncategorized');const d=String(x.item_description||'');return (n+' '+c+' '+d).toLowerCase().includes(q)}).slice(0,10).forEach(x=>add('item',x.id,getMenuDisplayName(x),getOriginalItemName(x),String(x.category||'Uncategorized')));if(!suggestions.length){d.innerHTML=`<div style="padding:12px;color:#667085;font-size:12px">${esc(T('empty'))}</div>`;d.classList.remove('hidden');return;}d.innerHTML=suggestions.slice(0,12).map((s,i)=>`<button type="button" class="search-suggestion" data-suggest-index="${i}"><span class="search-suggestion-type">${s.type==='category'?'CATEGORY':'ITEM'}</span><span class="search-suggestion-main">${esc(s.label)}</span><span class="search-suggestion-original">${s.type==='category'?esc(s.original):esc(s.original+(s.category?' · '+s.category:''))}</span></button>`).join('');d.classList.remove('hidden');d.querySelectorAll('[data-suggest-index]').forEach(b=>b.onclick=()=>selectSearchSuggestion(suggestions[Number(b.dataset.suggestIndex)]));}
function selectSearchSuggestion(s){if(!s)return;state.search='';if(s.type==='category'){state.cat=String(s.key);renderMenu();setTimeout(()=>{const btn=[...document.querySelectorAll('[data-cat]')].find(x=>x.dataset.cat===String(s.key));if(btn)btn.scrollIntoView({behavior:'smooth',block:'nearest'});const grid=$('#menuGrid');if(grid)grid.scrollIntoView({behavior:'smooth',block:'start'});},40);}else{state.cat=String(s.category||'Uncategorized');renderMenu();setTimeout(()=>{const card=document.querySelector(`[data-item-id="${CSS.escape(String(s.key))}"]`);if(card){card.scrollIntoView({behavior:'smooth',block:'center'});card.classList.add('search-highlight');setTimeout(()=>card.classList.remove('search-highlight'),1800);}},60);}}

function getMenuDisplayName(item){const original=getOriginalItemName(item);return shouldTranslateDatabaseContent(state.lang)?(trName(original,state.lang)||original):original;}
function getCategoryDisplayName(category){return category? (shouldTranslateDatabaseContent(state.lang)?(trText(category,state.lang)||category):category):'';}
function displayCategory(c){return getCategoryDisplayName(c)}
function filtered(){const q=state.search.toLowerCase();return state.menu.filter(x=>(state.cat==='ALL'||String(x.category||'Uncategorized')===state.cat)&&(!q||[x.name_en,x.category,x.item_description].join(' ').toLowerCase().includes(q)));}
function drawItems(isTake){const arr=filtered();$('#menuGrid').innerHTML=arr.length?arr.map(itemCard).join(''):`<div class="home-panel"><b>${esc(T('empty'))}</b></div>`;document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>add(Number(b.dataset.add),isTake));document.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>openImage(b.dataset.photo,b.dataset.name));document.querySelectorAll('[data-desc]').forEach(b=>b.onclick=()=>openDetails(Number(b.dataset.desc),isTake));document.querySelectorAll('[data-name]').forEach(b=>b.onclick=()=>openDetails(Number(b.dataset.name),isTake));}
function itemCard(x){const take=state.mode==='take',price=take?Number(x.takeaway_price||x.price||0):Number(x.dine_in_price||x.price||0),orig=getOriginalItemName(x),name=getMenuDisplayName(x),desc=trText(String(x.item_description||''),state.lang),img=x.image_url||'images/logo.png',out=x.schedule_status==='out_of_schedule';return `<article class="card" data-item-id="${Number(x.id)}"><img class="photo" src="${esc(img)}" data-photo="${esc(img)}" data-name="${esc(name)}" onerror="this.src='images/logo.png'"><div class="cardbody"><div class="itemname" data-name="${Number(x.id)}">${esc(name)}</div>${(state.lang==='en-US'||(state.lang!=='en'&&state.lang!=='ms'))&&name!==orig?`<div class="original">${esc(orig)}</div>`:''}<div class="desc" data-desc="${Number(x.id)}">${esc(desc||'Tap for full description')}</div><div class="price">RM ${price.toFixed(2)}</div>${out?`<div class="out">⏰ ${esc(T('outSchedule'))}</div>`:`<button class="add" data-add="${Number(x.id)}">＋ ${esc(T('add'))}</button>`}</div></article>`}
function renderSlider(){const box=$('#slider');if(!box)return;const top=[...state.menu].sort((a,b)=>Number(b.sold_quantity||0)-Number(a.sold_quantity||0)).slice(0,50);const slides=top.slice(0,15);if(!slides.length){box.innerHTML='<div style="padding:40px;text-align:center">No top-selling items yet.</div>';return}box.innerHTML=slides.map((x,i)=>`<div class="slide ${i===0?'active':''}" data-slide="${i}"><img src="${esc(x.image_url||'images/logo.png')}" data-photo="${esc(x.image_url||'images/logo.png')}" data-id="${Number(x.id)}" data-name="${esc(x.name_en||'')}" onerror="this.src='images/logo.png'"><div class="slide-info"><h2>${esc(getMenuDisplayName(x))}</h2><p>${esc(trText(x.item_description||'',state.lang))}</p><p style="margin-top:10px;font-weight:900;color:#a05d00">${Number(x.dine_in_price||x.price||0)?'RM '+Number(x.dine_in_price||x.price||0).toFixed(2):''}</p><small style="margin-top:8px;color:#667085">${esc(T('slideHint'))}</small></div></div>`).join('')+'<div class="dots">'+slides.map((_,i)=>`<span class="dot ${i===0?'active':''}" data-dot="${i}"></span>`).join('')+'</div>';box.querySelectorAll('[data-photo]').forEach(i=>i.onclick=()=>openDetails(Number(i.dataset.id),state.mode==='take'));let n=0;state.slideTimer=setInterval(()=>{const ss=box.querySelectorAll('.slide'),dd=box.querySelectorAll('.dot');if(!ss.length)return;n=(n+1)%ss.length;ss.forEach((s,i)=>s.classList.toggle('active',i===n));dd.forEach((d,i)=>d.classList.toggle('active',i===n));},5000);}
function stopSlide(){if(state.slideTimer){clearInterval(state.slideTimer);state.slideTimer=null}}
function add(id,isTake){const x=state.menu.find(m=>Number(m.id)===id);if(!x)return;const found=state.cart.find(c=>Number(c.id)===id&&c.mode===state.mode&&!(c.modifiers?.length||c.item_note));if(found)found.qty++;else state.cart.push({id,qty:1,mode:state.mode,modifiers:[],item_note:''});saveCart();updateCartBar();}
function saveCart(){localStorage.setItem('hameeds_cart',JSON.stringify(state.cart));}
function cartTotal(){return state.cart.reduce((s,c)=>{const x=state.menu.find(m=>Number(m.id)===Number(c.id));if(!x)return s;const p=c.mode==='take'?Number(x.takeaway_price||x.price||0):Number(x.dine_in_price||x.price||0);const extra=(c.modifiers||[]).reduce((a,m)=>a+Number(m.price||0),0);return s+(p+extra)*Number(c.qty||1)},0)}
function updateCartBar(){const n=state.cart.reduce((s,c)=>s+Number(c.qty||0),0);$('#cartTop').textContent=n;$('#cartCount').textContent=n;$('#cartTotal').textContent='RM '+cartTotal().toFixed(2);$('#cartBar').classList.toggle('show',n>0)}
function openCart(){
  const rows=state.cart.map((c,i)=>{const x=state.menu.find(m=>Number(m.id)===Number(c.id));if(!x)return '';const p=c.mode==='take'?Number(x.takeaway_price||x.price||0):Number(x.dine_in_price||x.price||0);const mods=Array.isArray(c.modifiers)?c.modifiers:[];const extra=mods.reduce((a,m)=>a+Number(m.price||0),0);const line=(p+extra)*Number(c.qty||1);const modHtml=mods.length?`<div class="cartmods">${mods.map(m=>`<span>${esc(m.text||m.name||'')}${Number(m.price||0)?` (+RM ${Number(m.price).toFixed(2)})`:''}</span>`).join('')}</div>`:'';const note=c.item_note?`<div class="cartnote">📝 ${esc(c.item_note)}</div>`:'';return `<div class="cartrow cartrow-rich"><div class="cartitemmain"><b>${esc(getMenuDisplayName(x))}</b><div class="original">${esc(c.mode==='take'?T('takeShort'):T('diningShort'))}</div>${modHtml}${note}<div class="cartactions"><button class="cartmodify" data-modify="${i}">✎ ${esc(CT('modify'))}</button><button class="cartnote-btn" data-note="${i}">📝 ${esc(CT('addNote'))}</button></div></div><div class="qty"><button data-q="-" data-i="${i}">−</button><b>${c.qty}</b><button data-q="+" data-i="${i}">+</button></div><b>RM ${line.toFixed(2)}</b></div>`}).join('');
  showModal(T('cart'),`<div>${rows||T('empty')}</div><div style="display:flex;justify-content:space-between;padding-top:14px;font-size:18px;font-weight:900"><span>${esc(T('total'))}</span><span>RM ${cartTotal().toFixed(2)}</span></div><div style="margin-top:14px;text-align:right"><button class="primary" id="checkoutBtn">${esc(T('checkout'))}</button></div>`);
  document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.i);state.cart[i].qty+=b.dataset.q==='+'?1:-1;if(state.cart[i].qty<=0)state.cart.splice(i,1);saveCart();updateCartBar();openCart();});
  document.querySelectorAll('[data-modify]').forEach(b=>b.onclick=()=>openModify(Number(b.dataset.modify)));
  document.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>openNote(Number(b.dataset.note)));
  $('#checkoutBtn')?.addEventListener('click',checkout);
}
function openModify(i){
  const c=state.cart[i];if(!c)return;const selected=new Set((c.modifiers||[]).map(m=>String(m.text||m.name||'').toLowerCase()));
  const groups={};for(const m of (state.mods||[])){const k=String(m.category||'Other').trim()||'Other';(groups[k]||(groups[k]=[])).push(m)}
  const body=Object.keys(groups).sort().map(cat=>`<div class="modifier-group"><div class="modifier-title">${esc(cat)}</div>${groups[cat].map(m=>{const key=String(m.modifier_name||'').toLowerCase();const checked=selected.has(key);return `<label class="modifier-option"><input type="checkbox" class="modifier-check" value="${esc(m.modifier_name||'')}" data-price="${Number(m.price||0)}" ${checked?'checked':''}><span>${esc(m.modifier_name||'')}</span><strong>${Number(m.price||0)?'+ RM '+Number(m.price).toFixed(2):''}</strong></label>`}).join('')}</div>`).join('')||`<div class="notice">${esc(CT('noModifiers'))}</div>`;
  showModal(CT('modify'),`${body}<div class="modifier-footer"><span>${esc(CT('selected'))}: <b id="modifierSelectedCount">0</b></span><button class="primary" id="saveModifiers">${esc(CT('save'))}</button></div>`);
  const refresh=()=>{$('#modifierSelectedCount').textContent=document.querySelectorAll('.modifier-check:checked').length};document.querySelectorAll('.modifier-check').forEach(x=>x.onchange=refresh);refresh();
  $('#saveModifiers').onclick=()=>{c.modifiers=[...document.querySelectorAll('.modifier-check:checked')].map(x=>({text:x.value,price:Number(x.dataset.price||0)}));if(!c.item_note)c.item_note='';saveCart();updateCartBar();openCart();};
}
function openNote(i){
  const c=state.cart[i];if(!c)return;const current=String(c.item_note||'');
  showModal(CT('customNote'),`<label style="display:block;font-weight:900;margin-bottom:7px">${esc(CT('customNote'))}</label><textarea id="cartNoteInput" class="field" rows="5" maxlength="500" placeholder="${esc(CT('notePlaceholder'))}">${esc(current)}</textarea><div class="note-count"><span id="noteCount">${current.length}</span>/500</div><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:12px"><button class="iconbtn" id="cancelNote">${esc(CT('cancel'))}</button><button class="primary" id="saveNote">${esc(CT('save'))}</button></div>`);
  $('#cartNoteInput').oninput=e=>$('#noteCount').textContent=e.target.value.length;$('#cancelNote').onclick=closeModal;$('#saveNote').onclick=()=>{c.item_note=$('#cartNoteInput').value.trim().slice(0,500);saveCart();openCart();};
}

function tableOptions(selected=''){return `<option value="">${esc(T('selectTable'))}</option>`+TABLES.map(t=>`<option value="${t}" ${selected===t?'selected':''}>${t}</option>`).join('');}
async function ensureManualTable(table){const t=String(table||'').trim().toUpperCase();if(!/^[ABC](?:[1-9]|[12][0-9]|30)$/.test(t))throw new Error(T('selectTable'));const r=await api('/table/manual-select',{method:'POST',body:JSON.stringify({table_id:t})});state.table=r.table_id;state.manualToken=r.manual_token||'';localStorage.setItem('hameeds_table',state.table);if(state.manualToken)localStorage.setItem('hameeds_manual_table_token',state.manualToken);return r;}
function checkout(){if(!state.cart.length)return;const dining=state.cart.some(c=>c.mode==='dining');const cust=state.customer||{};const tableHtml=dining?(state.qrKey?`<div class="notice">🔒 ${esc(T('table'))}: ${esc(state.table)} — ${esc(T('tableLocked'))}</div>`:`<label>${esc(T('table'))}</label><select id="checkoutTable" class="select" style="width:100%;margin-top:6px">${tableOptions(state.table)}</select>`):'';showModal(T('checkout'),`${tableHtml}<div class="notice" style="margin-top:12px">${esc(T('verify'))}</div><div class="checkout-grid"><div><label>${esc(T('name'))}</label><input id="cName" class="field" value="${esc(cust.full_name||'')}"></div><div><label>${esc(T('phone'))}</label><input id="cPhone" class="field" inputmode="tel" value="${esc(cust.phone||'')}"></div></div><div class="notice" style="margin-top:12px">${esc(T('orderType'))}: ${esc(dining?T('diningShort'):T('takeShort'))}${state.table?' · '+esc(T('table')+': '+state.table):''}</div><div style="text-align:right"><button class="primary" id="placeOrder">${esc(T('place'))} — RM ${cartTotal().toFixed(2)}</button></div>`);$('#placeOrder').onclick=placeOrder;}
async function placeOrder(){const name=$('#cName').value.trim(),phone=$('#cPhone').value.trim();if(!name||phone.replace(/\D/g,'').length<7){alert('Please enter a valid name and phone number.');return}const dining=state.cart.some(c=>c.mode==='dining');try{if(dining&&!state.qrKey){const selected=$('#checkoutTable')?.value||state.table;if(!selected)throw new Error(T('selectTable'));await ensureManualTable(selected);}const prof=await api('/customer/guest-profile',{method:'POST',body:JSON.stringify({full_name:name,phone})});state.customer={...prof.customer,token:prof.token};localStorage.setItem('hameeds_customer',JSON.stringify(state.customer));const items=state.cart.map(c=>({menu_item_id:c.id,quantity:c.qty,modifiers:Array.isArray(c.modifiers)?c.modifiers:[],item_note:String(c.item_note||'')}));const r=await api('/orders',{method:'POST',body:JSON.stringify({order_type:dining?'dine_in':'takeaway',table_id:dining?state.table:'',qr_table:dining&&state.qrKey?state.table:'',qr_key:dining&&state.qrKey?state.qrKey:'',manual_table_token:dining&&!state.qrKey?state.manualToken:'',customer_name:name,customer_phone:phone,items})});state.cart=[];saveCart();updateCartBar();closeModal();showModal('✓ '+T('orderPlaced'),`<div class="notice">Order #${esc(r.order?.id)}<br>${esc(T('total'))}: RM ${Number(r.order?.total_amount||0).toFixed(2)}</div><div style="text-align:right"><button class="primary" id="historyNow">${esc(T('history'))}</button></div>`);$('#historyNow').onclick=()=>{closeModal();state.mode='history';renderHistory();};}catch(e){alert(e.message)}}
async function renderHistory(){refreshChrome();state.mode='history';$('#appMain').innerHTML=`<section class="home-panel"><div class="toolbar"><button class="iconbtn" id="backHome">← Home</button><strong style="color:var(--blue)">${esc(T('history'))}</strong></div><div class="checkout-grid"><input id="historyPhone" class="field" inputmode="tel" placeholder="${esc(T('historyPhone'))}" value="${esc(state.customer?.phone||'')}"><button class="primary" id="findHistory">${esc(T('find'))}</button></div><div id="historyList" style="margin-top:14px"></div></section>`;$('#backHome').onclick=()=>renderHome();$('#findHistory').onclick=loadHistory;if(state.customer?.phone)loadHistory();}
async function loadHistory(){const phone=$('#historyPhone').value.trim();if(phone)try{const p=await api('/customer/guest-profile',{method:'POST',body:JSON.stringify({phone,full_name:state.customer?.full_name||''})});state.customer={...p.customer,token:p.token};localStorage.setItem('hameeds_customer',JSON.stringify(state.customer));const r=await api('/customer/orders');drawHistory(r.data||[]);}catch(e){$('#historyList').innerHTML='<div class="notice">'+esc(e.message)+'</div>'}else $('#historyList').innerHTML='<div class="notice">'+esc(T('historyPhone'))+'</div>'}
function drawHistory(arr){$('#historyList').innerHTML=arr.length?arr.map(o=>`<div class="history-card"><b>Order #${esc(o.id)}</b><span style="float:right;font-weight:900">RM ${Number(o.total_amount||0).toFixed(2)}</span><div class="original">${esc(o.order_type||'')} · ${esc(o.status||'')} · ${new Date(o.created_at).toLocaleString()}</div><div class="history-items">Table: ${esc(o.table_id||'—')} · ${esc(o.customer_name||'')}</div></div>`).join(''):`<div class="notice">${esc(T('noHistory'))}</div>`}
function showWaiter(){const locked=!!state.qrKey;const tableBlock=locked?`<div class="notice">🔒 ${esc(T('table'))}: <b>${esc(state.table)}</b> — ${esc(T('tableLocked'))}</div>`:`<label>${esc(T('table'))}</label><select id="wTable" class="select" style="width:100%;margin-top:6px">${tableOptions(state.table)}</select>`;showModal(T('waiter'),`${tableBlock}<div class="notice" style="margin-top:10px">${esc(state.customer?.full_name||'')}</div><div style="text-align:right;margin-top:12px"><button class="primary" id="callWaiterBtn">🔔 ${esc(T('call'))}</button></div>`);$('#callWaiterBtn').onclick=async()=>{try{let body;if(locked){body={qr_table:state.table,qr_key:state.qrKey,full_name:state.customer?.full_name||'',customer_phone:state.customer?.phone||''};}else{const selected=$('#wTable')?.value||'';if(!selected){alert(T('selectTable'));return}const r=await ensureManualTable(selected);body={table_id:r.table_id,manual_table_token:r.manual_token,full_name:state.customer?.full_name||'',customer_phone:state.customer?.phone||''};}await api('/waiter/call',{method:'POST',body:JSON.stringify(body)});closeModal();alert('Waiter has been called.');}catch(e){console.error('[Hameeds Customer] Waiter call failed:',e);alert(e.message)}}}
function showLanguage(){showModal('🌐 Language',`<div class="langgrid">${langs.map(([id,flag,name])=>`<button class="langoption ${state.lang===id?'active':''}" data-lang="${id}">${flag} ${esc(name)}</button>`).join('')}</div>`);document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=async()=>{const selected=String(b.dataset.lang||'en').trim();state.lang=selected;try{localStorage.setItem('hameeds_lang',selected);}catch(e){}closeModal();refreshChrome();renderCurrent();if(selected!=='ms'){await translateForLanguage(selected);renderCurrent();}else{state.translations={};renderCurrent();}});}

function openDetails(id,isTake){const x=state.menu.find(m=>Number(m.id)===id);if(!x)return;const translated=getMenuDisplayName(x),orig=x.name_en,desc=trText(x.item_description||'',state.lang),img=x.image_url||'images/logo.png',price=isTake?Number(x.takeaway_price||x.price||0):Number(x.dine_in_price||x.price||0);showModal(T('details'),`<img src="${esc(img)}" id="detailImage" style="width:100%;max-height:360px;object-fit:contain;background:#f2f4f7;border-radius:14px;cursor:zoom-in"><h2 style="color:var(--blue)">${esc(translated)}</h2>${state.lang!=='ms'&&translated!==orig?`<div class="original" style="font-size:13px">${esc(orig)}</div>`:''}<p style="white-space:pre-wrap;line-height:1.6">${esc(desc||'No description')}</p><b style="color:#a05d00">RM ${price.toFixed(2)}</b><button class="add" id="detailAdd">＋ ${esc(T('add'))}</button>`);$('#detailImage').onclick=()=>openImage(img,translated);$('#detailAdd').onclick=()=>{add(id,isTake);closeModal();};}
function openImage(src,title){showModal('',`<div class="image-stage" id="imageStage"><img id="zoomImg" src="${esc(src)}" alt="${esc(title||'')}"></div><div class="zoomtools"><button id="zoomOut">−</button><button id="zoomReset">Reset</button><button id="zoomIn">+</button></div>`,'image-modal');let scale=1,x=0,y=0,drag=false,sx=0,sy=0;const img=$('#zoomImg'),stage=$('#imageStage');const apply=()=>img.style.transform=`translate(${x}px,${y}px) scale(${scale})`;$('#zoomIn').onclick=()=>{scale=Math.min(5,scale+.25);apply()};$('#zoomOut').onclick=()=>{scale=Math.max(.5,scale-.25);apply()};$('#zoomReset').onclick=()=>{scale=1;x=0;y=0;apply()};stage.addEventListener('wheel',e=>{e.preventDefault();scale=Math.max(.5,Math.min(5,scale+(e.deltaY<0?.2:-.2)));apply()},{passive:false});stage.addEventListener('pointerdown',e=>{drag=true;sx=e.clientX-x;sy=e.clientY-y;stage.setPointerCapture(e.pointerId)});stage.addEventListener('pointermove',e=>{if(!drag)return;x=e.clientX-sx;y=e.clientY-sy;apply()});stage.addEventListener('pointerup',()=>drag=false);}
let lastScrollY=window.scrollY||0;let scrollChromeBound=false;function setupScrollChrome(){if(scrollChromeBound)return;scrollChromeBound=true;window.addEventListener('scroll',()=>{if(state.mode!=='dining'&&state.mode!=='take')return;const y=window.scrollY||0,h=document.querySelector('.header');if(!h)return;if(y>lastScrollY+4&&y>40)h.classList.add('is-hidden');else if(y<lastScrollY-4)h.classList.remove('is-hidden');lastScrollY=y;},{passive:true});}
