function checkout(){if(!state.cart.length)return;if(!state.customerOrderingEnabled){alert(T('menuOnly'));return}const dining=state.cart.some(c=>c.mode==='dining'),sub=cartSubtotal(),sst=Math.round(sub*.06*100)/100,total=Math.round((sub+sst)*100)/100,c=state.customer||{};const table=dining?(state.qrKey?`<div class="notice">🔒 ${esc(T('table'))}: ${esc(state.table)}</div>`:`<label>${esc(T('table'))}</label><select id="checkoutTable" class="select" style="width:100%">${tableOptions(state.table)}</select>`):'';showModal(T('checkout'),`${table}<div class="checkout-grid"><div><label>${esc(T('name'))}</label><input id="cName" class="field" value="${esc(c.full_name||'')}"></div><div><label>${esc(T('phone'))}</label><input id="cPhone" class="field" value="${esc(c.phone||'')}" inputmode="tel"></div></div><div class="cart-summary"><div><span>${esc(T('subtotal'))}</span><b>RM ${sub.toFixed(2)}</b></div><div><span>SST 6%</span><b>RM ${sst.toFixed(2)}</b></div><div class="grand"><span>${esc(T('total'))}</span><b>RM ${total.toFixed(2)}</b></div></div><div style="text-align:right"><button class="primary" id="placeOrder">${esc(T('place'))}</button></div>`);$('#placeOrder').onclick=placeOrder}
async function placeOrder(){const name=$('#cName').value.trim(),phone=$('#cPhone').value.trim();if(!name||phone.replace(/\D/g,'').length<7){alert('Please enter a valid name and phone number.');return}try{const dining=state.cart.some(c=>c.mode==='dining');if(dining&&!state.qrKey){const t=$('#checkoutTable')?.value||state.table;if(!t)throw new Error(T('selectTable'));await ensureManualTable(t)}const items=state.cart.map(c=>({menu_item_id:c.id,quantity:c.qty,modifiers:c.modifiers||[],item_note:c.item_note||''}));let r;if(state.addMoreOrderId){r=await api('/orders/'+state.addMoreOrderId+'/add-more',{method:'POST',body:JSON.stringify({customer_name:name,items})});state.addMoreOrderId=null}else{const p=await api('/customer/guest-profile',{method:'POST',body:JSON.stringify({full_name:name,phone})});state.customer={...p.customer,token:p.token};localStorage.setItem('hameeds_customer',JSON.stringify(state.customer));r=await api('/orders',{method:'POST',body:JSON.stringify({order_type:dining?'dine_in':'takeaway',table_id:dining?state.table:'',qr_table:dining&&state.qrKey?state.table:'',qr_key:dining&&state.qrKey?state.qrKey:'',manual_table_token:dining&&!state.qrKey?state.manualToken:'',customer_name:name,customer_phone:phone,items})})}state.cart=[];saveCart();updateCartBar();closeModal();showModal('✓ '+T('orderPlaced'),`<div class="notice">Order #${esc(r.order?.id||r.request?.order_id)}</div>`)}catch(e){alert(e.message)}}
function orderCompletedV7(o){const s=String(o?.status||'').toLowerCase(),p=String(o?.payment_status||'').toLowerCase();return ['completed','paid','closed','served','delivered'].includes(s)||['completed','paid'].includes(p)}
