  const header=['No.-11, Jalan KLIA Avenue, Pusat Perdagangan KLIA','Avenue, Sepang, 43900','Tel: +60 387059807 | Email: prokashlaptop@gmail.com','SST ID: N/A','Table: '+(order.table_id||'N/A'),'Date: '+new Date(invoice?.created_at||order.created_at||Date.now()).toLocaleString()];
  if(invoice?.payment_method)header.push('Payment: '+invoice.payment_method);
