    for(let ci=0;ci<chunks.length;ci++){
      if(row.mod){text(14,cy,chunks[ci],8.8,false);cy-=11;}
      else{if(ci===0){text(8,cy,chunks[ci]+' (x'+row.qty+')',9,true);text(160,cy,'RM'+Number(row.line).toFixed(2),9,true);}else text(8,cy,chunks[ci],9,true);cy-=12;}
    }
