  cy=totalRow(cy,'Subtotal:','RM'+sub.toFixed(2));cy=totalRow(cy,'SST (6%):','RM'+sst.toFixed(2));cy=totalRow(cy,'Rounding:',(rounding>=0?'+':'')+'RM'+rounding.toFixed(2));if(discount>0)cy=totalRow(cy,'Discount:','- RM'+discount.toFixed(2));
  commands.push(`0.7 w 10 ${cy+7} m ${w-10} ${cy+7} l S`);cy-=5;cy=totalRow(cy,'TOTAL PAID:','RM'+totalPaid.toFixed(2),16,true);center(cy+2,'PAID',10,true);cy-=18;
  const bw=68,bh=15,scale=bw/receiptCode39Rects(order.id).width,bcBase=(w-bw)/2,barY=cy-bh*2.834,encoded='*'+String(Math.max(0,Number(order.id)||0))+'*',map={'0':'nnnwwnwnn','1':'wnnwnnnnw','2':'nnwwnnnnw','3':'wnwwnnnnn','4':'nnnwwnnnw','5':'wnnwwnnnn','6':'nnwwwnnnn','7':'nnnwnnwnw','8':'wnnwnnwnn','9':'nnwwnnwnn','*':'nwnnwnwnn'};
  commands.push(`0.5 w [2 2] 0 d 8 ${cy+5} m ${w-8} ${cy+5} l S [] 0 d`);let bx=bcBase+12*scale;
  for(let ci=0;ci<encoded.length;ci++){const pat=map[encoded[ci]]||map['0'];for(let j=0;j<pat.length;j++){const rawW=pat[j]==='w'?4.2:1.6,barW=rawW*scale;if(j%2===0)commands.push(`0 0 0 rg ${bx.toFixed(2)} ${barY.toFixed(2)} ${barW.toFixed(2)} ${(bh*2.834).toFixed(2)} re f`);bx+=barW;}if(ci<encoded.length-1)bx+=1.6*scale;}
  center(barY-12,'ORDER ID: '+order.id,9,true);
  const enc=new TextEncoder(),u8=s=>enc.encode(s),join=(arr)=>{let n=arr.reduce((a,b)=>a+b.length,0),o=new Uint8Array(n),p=0;for(const b of arr){o.set(b,p);p+=b.length;}return o;};
  const objs=[];objs.push(join([u8('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\n')]));objs.push(join([u8('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>\n')]));
  let imageObj=0;if(logo){imageObj=3;objs.push(join([u8(`<< /Type /XObject /Subtype /Image /Width ${logo.width} /Height ${logo.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${logo.bytes.length} >>\nstream\n`),logo.bytes,u8('\nendstream\n')]));}
  const content=u8(commands.join('\n'));
