function v18Candidates(item,field){const tr=getItemTranslations(item);const pick=(...xs)=>xs.map(v=>String(v??'').trim()).find(Boolean)||'';if(field==='name')return{malay:pick(item.name_ms,item.name_malay,item.name_bm,tr.ms,tr.malay),english:pick(item.name_en,item.name,tr.en,tr.en_us,tr['en-US'])};if(field==='category')return{malay:pick(item.category_ms,item.category_malay,item.category_bm,tr.category_ms,tr.category_malay),english:pick(item.category_en,tr.category_en,tr.category_en_us),fallbackMalay:pick(item.category)};return{malay:pick(item.description_ms,item.description_malay,item.description_bm,tr.description_ms,tr.description_malay),english:pick(item.description_en,item.description,tr.description_en,tr.description_en_us),fallbackMalay:pick(item.item_description)};}
function v18SourcePair(item,field){const c=v18Candidates(item,field);return{malay:c.malay||'',english:c.english||'',fallbackMalay:c.fallbackMalay||''};}
function v18IsMeaningfulTranslation(source,result,target){const a=String(source||'').trim().toLowerCase(),b=String(result||'').trim().toLowerCase();if(!b||!a)return false;if(a===b&&target!=='ms')return false;return true;}
async function v18Google(text,target,source){const q=String(text||'').trim();if(!q)return'';const tl=googleTargetLang[target]||target;const sl=source||'auto';const url='https://translate.googleapis.com/translate_a/single?client=gtx&sl='+encodeURIComponent(sl)+'&tl='+encodeURIComponent(tl)+'&dt=t&q='+encodeURIComponent(q);const r=await fetch(url);if(!r.ok)throw new Error('Google Translate HTTP '+r.status);const d=await r.json();return Array.isArray(d?.[0])?d[0].map(x=>x?.[0]||'').join('').trim():'';}
async function v18MyMemory(text,target,source){const q=String(text||'').trim();if(!q)return'';const tl=googleTargetLang[target]||target;const sl=source||'autodetect';const url='https://api.mymemory.translated.net/get?q='+encodeURIComponent(q)+'&langpair='+encodeURIComponent(sl+'|'+tl);const r=await fetch(url);if(!r.ok)throw new Error('MyMemory HTTP '+r.status);const d=await r.json();return String(d?.responseData?.translatedText||'').trim();}
async function v18TranslateOne(text,target,candidates){const original=String(text||'').trim();const seen=new Set();for(const src of candidates||[]){const s=String(src?.text||'').trim(),code=String(src?.code||'auto').trim();if(!s||seen.has(code+'|'+s))continue;seen.add(code+'|'+s);if((target==='en'||target==='en-US')&&code==='en'&&s===original)return s;try{const g=await v18Google(s,target,code);if(v18IsMeaningfulTranslation(s,g,target))return normalizeMalayRestaurantTranslation(s,g,target);}catch(e){}try{const m=await v18MyMemory(s,target,code);if(v18IsMeaningfulTranslation(s,m,target))return normalizeMalayRestaurantTranslation(s,m,target);}catch(e){}}try{const g=await v18Google(original,target,'auto');if(v18IsMeaningfulTranslation(original,g,target))return normalizeMalayRestaurantTranslation(original,g,target);}catch(e){}try{const m=await v18MyMemory(original,target,'autodetect');if(v18IsMeaningfulTranslation(original,m,target))return normalizeMalayRestaurantTranslation(original,m,target);}catch(e){}/* Last-resort word-by-word fallback, only after both services fail on the phrase. */const words=original.split(/(\s+)/);if(words.filter(w=>/\S/.test(w)).length<=14){const out=[];for(const token of words){if(/\s+/.test(token)){out.push(token);continue;}let piece='';try{piece=await v18Google(token,target,'auto');}catch(e){}if(!v18IsMeaningfulTranslation(token,piece,target)){try{piece=await v18MyMemory(token,target,'autodetect');}catch(e){}}out.push(piece&&v18IsMeaningfulTranslation(token,piece,target)?piece:token);}const joined=out.join('').trim();if(joined&&joined!==original)return normalizeMalayRestaurantTranslation(original,joined,target);}return original;}
function v18CacheGet(lang,text){try{return localStorage.getItem('hameeds_tr_v3_'+lang+'|'+text)||''}catch(e){return''}}
function v18CacheSet(lang,text,value){try{localStorage.setItem('hameeds_tr_v3_'+lang+'|'+text,value)}catch(e){}}
async function v18TranslateItemField(item,field,target){const src=v18SourcePair(item,field);const primary=src.malay||src.fallbackMalay||src.english;if(!primary)return'';const cached=v18CacheGet(target,primary);if(cached)return cached;const candidates=[];if(src.malay)candidates.push({text:src.malay,code:'ms'});if(src.english&&src.english!==src.malay)candidates.push({text:src.english,code:'en'});if(src.fallbackMalay&&src.fallbackMalay!==src.malay&&src.fallbackMalay!==src.english)candidates.push({text:src.fallbackMalay,code:'ms'});const out=await v18TranslateOne(primary,target,candidates);v18CacheSet(target,primary,out||primary);return out||primary;}
async function v18TranslateCategory(category,target){const cat=String(category||'').trim();if(!cat)return;const items=state.menu.filter(x=>String(x.category||'Uncategorized')===cat);const unique=new Map();for(const item of items){const fields=target==='en'?['description']:['name','category','description'];for(const field of fields){const src=v18SourcePair(item,field),key=src.malay||src.fallbackMalay||src.english;if(key&&!unique.has(field+'|'+key))unique.set(field+'|'+key,{item,field,key});}}const jobs=[...unique.values()];for(let i=0;i<jobs.length;i+=2){await Promise.all(jobs.slice(i,i+2).map(async job=>{const v=await v18TranslateItemField(job.item,job.field,target);state.translations[v18TranslationKey(target,job.key)]=v;}));}}
let v18TranslationGeneration=0,v18TranslatedCategories=new Set(),v18TranslationRunning=new Map();
async function ensureV18CategoryTranslated(category){const target=v18NormLang(state.lang),cat=String(category||'').trim();if(target==='ms'||!cat)return;const key=target+'|'+cat;if(v18TranslatedCategories.has(key))return;if(v18TranslationRunning.has(key))return v18TranslationRunning.get(key);const generation=v18TranslationGeneration;const p=(async()=>{try{await v18TranslateCategory(cat,target);if(generation===v18TranslationGeneration){v18TranslatedCategories.add(key);if(state.mode==='dining'||state.mode==='take')drawItems(state.mode==='take');}}catch(e){console.warn('[Hameeds Customer] category translation failed:',e.message)}finally{v18TranslationRunning.delete(key)}})();v18TranslationRunning.set(key,p);return p;}
async function translateForLanguage(lang){v18TranslationGeneration++;v18TranslatedCategories=new Set();v18TranslationRunning.clear();state.translations={};const target=v18NormLang(lang);if(target==='ms')return;/* English = description only. English (US) = name/category/description. Other languages = all database content. */const active=document.querySelectorAll('[data-menu-category]');const first=active[0]?.dataset.menuCategory;if(first&&first!=='menu-section-top15'){const cat=state.cats.find(c=>'menu-section-'+slug(c)===first);if(cat)await ensureV18CategoryTranslated(cat);}}
function v18TranslationFor(text,lang){const key=String(text||'');if(!key)return'';const target=v18NormLang(lang);if(target==='ms')return key;return state.translations[v18TranslationKey(target,key)]||v18CacheGet(target,key)||key;}
function trText(text,lang){const key=String(text||'');if(!key)return'';const target=v18NormLang(lang);if(target==='ms')return key;return v18TranslationFor(key,target);}
function trName(text,lang){const key=String(text||'');if(!key)return'';const target=v18NormLang(lang);if(target==='ms'||target==='en')return key;return v18TranslationFor(key,target);}
function shouldTranslateDatabaseContent(lang=state.lang){const target=v18NormLang(lang);return target!=='ms'&&target!=='en';}
function getOriginalItemName(item){const tr=getItemTranslations(item);return String(item.name_en||item.name||item.item_name||tr.en||tr.en_us||item.name_ms||tr.ms||item.name_bn||tr.bn||item.name_hi||tr.hi||item.name_ta||tr.ta||item.name_ar||tr.ar||item.name_zh||tr.zh||'').trim();}
function getMenuDisplayName(item){const orig=getOriginalItemName(item),target=v18NormLang(state.lang);if(target==='ms'||target==='en')return orig;const src=v18SourcePair(item,'name'),key=src.malay||src.fallbackMalay||src.english;return v18TranslationFor(key,target)||orig;}
function getCategoryDisplayName(category){const target=v18NormLang(state.lang);if(!category||target==='ms'||target==='en')return category||'';return v18TranslationFor(String(category),target)||category;}
function displayCategory(c){return getCategoryDisplayName(c)}
function v18OriginalForDisplay(item){const src=v18SourcePair(item,'name');return src.malay||src.fallbackMalay||src.english||getOriginalItemName(item);}
function itemCard(x){const take=state.mode==='take',price=take?Number(x.takeaway_price||x.price||0):Number(x.dine_in_price||x.price||0),orig=v18OriginalForDisplay(x),name=getMenuDisplayName(x),ds=v18SourcePair(x,'description'),descKey=ds.malay||ds.fallbackMalay||ds.english,desc=trText(descKey,state.lang),img=x.image_url||'images/logo.png',out=x.schedule_status==='out_of_schedule',showOriginal=v18NormLang(state.lang)!=='ms'&&v18NormLang(state.lang)!=='en'&&name!==orig;return `<article class="card"><img class="photo" src="${esc(img)}" data-photo="${esc(img)}" data-name="${esc(name)}" data-original="${esc(orig)}" onerror="this.src='images/logo.png'"><div class="cardbody"><div class="itemname" data-name="${Number(x.id)}">${esc(name)}</div>${showOriginal?`<div class="original">${esc(orig)}</div>`:''}<div class="desc" data-desc="${Number(x.id)}">${esc(desc||'Tap for full description')}</div><div class="price">RM ${price.toFixed(2)}</div>${out?`<div class="out">⏰ ${esc(T('outSchedule'))}</div>`:(state.customerOrderingEnabled?`<button class="add" data-add="${Number(x.id)}">＋ ${esc(T('add'))}</button>`:'')}</div></article>`;}
function openImage(src,title,original){showModal('',`<div style="text-align:center;margin-bottom:8px"><div style="font-size:20px;font-weight:900;color:#fff">${esc(title||'')}</div>${original&&original!==title?`<div style="font-size:12px;color:#ddd;margin-top:3px">${esc(original)}</div>`:''}</div><div class="image-stage" id="imageStage"><img id="zoomImg" src="${esc(src)}" alt="${esc(title||'')}"></div><div class="zoomtools"><button id="zoomOut">−</button><button id="zoomReset">Reset</button><button id="zoomIn">+</button></div>`,'image-modal');let scale=1,x=0,y=0,drag=false,sx=0,sy=0;const img=$('#zoomImg'),stage=$('#imageStage'),apply=()=>img.style.transform=`translate(${x}px,${y}px) scale(${scale})`;$('#zoomIn').onclick=()=>{scale=Math.min(5,scale+.25);apply()};$('#zoomOut').onclick=()=>{scale=Math.max(.5,scale-.25);apply()};$('#zoomReset').onclick=()=>{scale=1;x=0;y=0;apply()};stage.addEventListener('wheel',e=>{e.preventDefault();scale=Math.max(.5,Math.min(5,scale+(e.deltaY<0?.2:-.2)));apply()},{passive:false});stage.addEventListener('pointerdown',e=>{drag=true;sx=e.clientX-x;sy=e.clientY-y;stage.setPointerCapture(e.pointerId)});stage.addEventListener('pointermove',e=>{if(!drag)return;x=e.clientX-sx;y=e.clientY-sy;apply()});stage.addEventListener('pointerup',()=>drag=false);}
function v18SearchText(item){const tr=getItemTranslations(item);return [item.name_en,item.name,item.item_name,item.name_ms,tr.en,tr.ms,item.category,item.category_ms,item.category_en,item.item_description,item.description].filter(Boolean).join(' ').toLowerCase();}
function closeV18SearchDropdown(){const d=$('#searchDropdown')||$('#menuSearchDropdown');if(d){d.innerHTML='';d.classList.add('hidden');}}
function selectV18SearchSuggestion(r){const input=$('#search');if(!r||!input)return;closeV18SearchDropdown();state.search='';input.value='';if(r.type==='category'){state.cat=r.value;drawItems(state.mode==='take');setTimeout(()=>{scrollMenuV7('menu-section-'+slug(r.value));ensureV18CategoryTranslated(r.value);},60);}else{state.cat='ALL';drawItems(state.mode==='take');setTimeout(()=>{const el=document.querySelector(`.card[data-item-id="${Number(r.id)}"]`)||document.querySelector(`[data-name="${Number(r.id)}"]`)?.closest('.card');if(el){el.scrollIntoView({behavior:'smooth',block:'center'});el.classList.add('search-highlight');setTimeout(()=>el.classList.remove('search-highlight'),1800);}ensureV18CategoryTranslated(r.value);},80);}}
function renderV18SearchDropdown(){const input=$('#search'),d=$('#searchDropdown');if(!input||!d)return;const q=String(input.value||'').trim().toLowerCase();d.innerHTML='';if(q.length<2){d.classList.add('hidden');return;}const cats=[];for(const c of state.cats){const a=String(c||'').toLowerCase(),b=String(displayCategory(c)||'').toLowerCase();if(a.includes(q)||b.includes(q))cats.push(c);}const items=state.menu.filter(x=>v18SearchText(x).includes(q));const out=[];cats.slice(0,5).forEach(c=>out.push({type:'category',value:c,label:displayCategory(c),original:c}));items.slice(0,10).forEach(x=>out.push({type:'item',id:Number(x.id),value:String(x.category||'Uncategorized'),label:getMenuDisplayName(x),original:v18OriginalForDisplay(x)}));if(!out.length){d.innerHTML=`<div style="padding:12px;color:#667085;font-size:12px">${esc(T('empty'))}</div>`;d.classList.remove('hidden');return;}d.innerHTML=out.slice(0,12).map((r,i)=>`<button type="button" class="search-suggestion" data-v18-sidx="${i}"><span class="search-suggestion-type">${r.type==='category'?'CATEGORY':'ITEM'}</span><span class="search-suggestion-main">${esc(r.label)}</span><span class="search-suggestion-original">${esc(r.original||'')}</span></button>`).join('');d.classList.remove('hidden');d.querySelectorAll('[data-v18-sidx]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();selectV18SearchSuggestion(out[Number(b.dataset.v18Sidx)]);});}
function drawItems(isTake){const top=[...state.menu].sort((a,b)=>Number(b.sold_quantity||0)-Number(a.sold_quantity||0)).slice(0,15),q=state.search.toLowerCase().trim(),match=a=>!q||v18SearchText(a).includes(q),groups=[{id:'menu-section-top15',name:T('top15'),items:top.filter(match)}];for(const c of state.cats)groups.push({id:'menu-section-'+slug(c),name:displayCategory(c),items:state.menu.filter(x=>String(x.category||'Uncategorized')===c).filter(match)});$('#menuGrid').innerHTML=groups.map(g=>`<section class="menu-category-section" id="${esc(g.id)}" data-menu-category="${esc(g.id)}"><div class="menu-category-heading">${esc(g.name)}</div><div class="grid">${g.items.length?g.items.map(itemCard).join(''):`<div class="notice">${esc(T('empty'))}</div>`}</div></section>`).join('');document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>add(Number(b.dataset.add),isTake));document.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>openImage(b.dataset.photo,b.dataset.name,b.dataset.original));document.querySelectorAll('[data-desc]').forEach(b=>b.onclick=()=>openDetails(Number(b.dataset.desc),isTake));document.querySelectorAll('[data-name]').forEach(b=>b.onclick=()=>openDetails(Number(b.dataset.name),isTake));setupMenuObserverV7();updateCategoryChromeV7();renderV18SearchDropdown();}
function renderMenu(){refreshChrome();const isTake=state.mode==='take',title=isTake?T('take'):T('dining');$('#appMain').innerHTML=`<section class="home-panel menu-panel">${state.customerOrderingEnabled?'':`<div class="menu-only-banner">🔒 ${esc(T('menuOnly'))}</div>`}<div class="toolbar menu-controls"><button class="iconbtn" id="backHome">← Home</button><strong style="color:var(--blue)">${esc(title)}</strong><span style="margin-left:auto">${state.table?esc(T('table')+': '+state.table):''}</span><div class="menu-search-row"><select id="catSelect" class="select"><option value="TOP15">${esc(T('top15'))}</option>${state.cats.map(c=>`<option value="${esc(c)}">${esc(displayCategory(c))}</option>`).join('')}</select><div class="search-wrap"><input id="search" class="search" placeholder="${esc(T('search'))}" value="${esc(state.search)}" autocomplete="off"><div id="searchDropdown" class="menu-search-dropdown hidden"></div></div></div><div class="categorybar"><button class="cat ${state.cat==='ALL'?'active':''}" data-cat="ALL">${esc(T('top15'))}</button>${state.cats.map(c=>`<button class="cat ${state.cat===c?'active':''}" data-cat="${esc(c)}">${esc(displayCategory(c))}</button>`).join('')}</div></div><div class="content"><div><div id="menuGrid"></div></div></div></section>`;$('#backHome').onclick=()=>{state.search='';state.cat='ALL';renderHome()};$('#catSelect').onchange=e=>{const v=e.target.value;state.cat=v==='TOP15'?'ALL':v;state.search='';drawItems(isTake);setTimeout(()=>scrollMenuV7(v==='TOP15'?'menu-section-top15':'menu-section-'+slug(v)),20);if(v!=='TOP15')ensureV18CategoryTranslated(v);};const search=$('#search');search.oninput=e=>{state.search=e.target.value;drawItems(isTake);renderV18SearchDropdown();};search.onfocus=()=>renderV18SearchDropdown();search.onkeydown=e=>{if(e.key==='Escape'){closeV18SearchDropdown();return;}if(e.key==='Enter'){const b=document.querySelector('#searchDropdown .search-suggestion');if(b){e.preventDefault();b.click();}}};document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{state.cat=b.dataset.cat;state.search='';drawItems(isTake);setTimeout(()=>scrollMenuV7(b.dataset.cat==='ALL'?'menu-section-top15':'menu-section-'+slug(b.dataset.cat)),20);if(b.dataset.cat!=='ALL')ensureV18CategoryTranslated(b.dataset.cat);});drawItems(isTake);setupScrollChrome();if(state.cats[0])ensureV18CategoryTranslated(state.cats[0]);}
function setupMenuObserverV7(){if(menuObsV7)menuObsV7.disconnect();menuObsV7=new IntersectionObserver(es=>{const e=es.filter(x=>x.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(!e)return;const id=e.target.dataset.menuCategory||'';const cat=id==='menu-section-top15'?'':(state.cats.find(c=>'menu-section-'+slug(c)===id)||'');if(cat){state.cat=cat;updateCategoryChromeV7();ensureV18CategoryTranslated(cat);}}, {rootMargin:'-125px 0px -55% 0px',threshold:[.1,.3,.6]});document.querySelectorAll('[data-menu-category]').forEach(e=>menuObsV7.observe(e));}


function v18LooksMalay(text){const t=String(text||'').toLowerCase().replace(/[^a-z0-9\s]/g,' ');const words=t.split(/\s+/).filter(Boolean);const known=['bihun','goreng','ayam','nasi','mee','mi','telur','kampung','sambal','kari','ikan','daging','sup','teh','kopi','air','limau','panas','sejuk','suam','besar','kecil','kosong','mamak','sayur','cili','pedas','manis','masin','susu','sirap','barli','gula','tanpa','tambah','asam','boi','roti','keju','cendawan','kunyit','tepung','kerabu','kelapa','epal','oren','nanas','tembikai','jus'];let hits=0;for(const w of words)if(known.includes(w))hits++;return hits>=1;}
function v18SourcePair(item,field){const c=v18Candidates(item,field);let malay=c.malay||c.fallbackMalay||'';let english=c.english||'';if(!malay&&english&&v18LooksMalay(english)){malay=english;english='';}return{malay,english,fallbackMalay:c.fallbackMalay||''};}


